  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_lifecycleConsistencyMonitor)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_lifecycleConsistencyMonitor)
  }

  /** helper function to set the values of all input ports.
   * @param dockReadiness payload for data port dockReadiness
   * @param serviceInterlock payload for data port serviceInterlock
   * @param lifecyclePrestate payload for data port lifecyclePrestate
   */
  def put_concrete_inputs(dockReadiness : Docked_Service_Access_Lifecycle_Supervisor.DockReadiness.Type,
                          serviceInterlock : Docked_Service_Access_Lifecycle_Supervisor.ServiceInterlock.Type,
                          lifecyclePrestate : Docked_Service_Access_Lifecycle_Supervisor.LifecycleState.Type): Unit = {
    put_dockReadiness(dockReadiness)
    put_serviceInterlock(serviceInterlock)
    put_lifecyclePrestate(lifecyclePrestate)
  }


  /** helper function to check LifecycleConsistencyMonitor_supervisorProcess_lifecycleConsistencyMonitor's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param operationalAssessment method that will be called with the value of the outgoing data
   *        port 'operationalAssessment'.
   */
  def check_concrete_output(operationalAssessment: Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val operationalAssessmentValue: Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment.Type = get_operationalAssessment().get
    if(!operationalAssessment(operationalAssessmentValue)) {
      testFailures = testFailures :+ st"'operationalAssessment' did not match expected: value of the outgoing data port is ${operationalAssessmentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_dockReadiness(value : Docked_Service_Access_Lifecycle_Supervisor.DockReadiness.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_lifecycleConsistencyMonitor.operational_api.dockReadiness_Id, Docked_Service_Access_Lifecycle_Supervisor.DockReadiness_Payload(value))
  }

  // setter for in DataPort
  def put_serviceInterlock(value : Docked_Service_Access_Lifecycle_Supervisor.ServiceInterlock.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_lifecycleConsistencyMonitor.operational_api.serviceInterlock_Id, Docked_Service_Access_Lifecycle_Supervisor.ServiceInterlock_Payload(value))
  }

  // setter for in DataPort
  def put_lifecyclePrestate(value : Docked_Service_Access_Lifecycle_Supervisor.LifecycleState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_lifecycleConsistencyMonitor.operational_api.lifecyclePrestate_Id, Docked_Service_Access_Lifecycle_Supervisor.LifecycleState_Payload(value))
  }

  // getter for out DataPort
  def get_operationalAssessment(): Option[Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment.Type] = {
    val value: Option[Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment.Type] = get_operationalAssessment_payload() match {
      case Some(Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port operationalAssessment.  Expecting 'Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment_Payload' but received ${v}")
      case _ => None[Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_operationalAssessment_payload(): Option[Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_lifecycleConsistencyMonitor.initialization_api.operationalAssessment_Id).asInstanceOf[Option[Docked_Service_Access_Lifecycle_Supervisor.OperationalAssessment_Payload]]
